import{S as t,o as n,c as e,a9 as h,B as l}from"./chunks/framework.DxG24V0C.js";const k="/agentsrc/images/opencode/06-context-assembly-pipeline.svg",p="/agentsrc/images/opencode/06-context-aware-injection.svg",c=JSON.parse('{"title":"OpenCode 上下文装配：持久知识、按需注入与窗口预算","description":"","frontmatter":{"title":"OpenCode 上下文装配：持久知识、按需注入与窗口预算"},"headers":[],"relativePath":"opencode/06-context.md","filePath":"opencode/06-context.md","lastUpdated":1788319991000}'),d={name:"opencode/06-context.md"},g=Object.assign(d,{setup(r){const i=[{question:"OpenCode 指令文件用「findUp 取首个匹配、不叠加各级父目录」，而不是把从工作目录到根的所有 AGENTS.md 都注入。这样设计的主要取舍是什么？",options:["首匹配丢弃父级约定换实现成本更低但牺牲可嵌套","取全部父级目录可获更全约束但不叠加会丢深层指令","首匹配保证行为确定可预测代价是丢弃部分父级约定","只加载项目根单个文件以简化权限与缓存逻辑"],correct:2,explanation:"源码注释明确「first project-level match wins so we don't stack...」。取首个匹配保证行为可预期，代价是父级目录里可能更有用的约定被丢弃。轮换成「全部叠加」则行为不可预测、覆盖规则复杂——这是简单可预测 vs 多层叠加的取舍。"},{question:"Skill 系统把完整内容留在磁盘，system prompt 里只放 name+description。这个「两阶段加载」对上下文装配的意义是什么？",options:["仅在输出阶段把 skill 名称重复一遍以提高可见性","只发描述省 token，要用时再通过 skill 工具取正文","两阶段本质相同只是分开写让代码更易维护","system 与工具各自加载一半保证内容不重复"],correct:1,explanation:"第一阶段 system 只放可用的 name+description（轻量），第二阶段 LLM 判断匹配后调 skill 工具加载 content（按需）。这避免了「所有 skill 全文都塞进 prompt」的 token 浪费，是「描述轻、内容贵、按需取」的典型。"},{question:"instruction.resolve 在 Read 工具读文件时把 nearby 指令注入到工具结果的 system-reminder，而不全塞进 system prompt。这套「按需 + 上下文相关」的核心收益是什么？",options:["把指令转移到消息里从而绕开 provider 对 system 的长度限制","只在读某目录时才给它该目录约定省 token 且精准","让全部指令都能在每一条消息里重复可见以提高准确性","必要时可跳过指令文件的磁盘读取直接复用缓存"],correct:1,explanation:"全塞 system 会撑 token 且给无关上下文。resolve 让 LLM 真读 src/auth 时才注入 src/auth/AGENTS.md，并通过 claims 去重（同一 assistant 消息只注入一次），兼顾省 token 与精准，是「预检索」的反面。"},{question:"OpenCode 为什么用 Grep/Read 这类工具让 LLM 自己搜，而不是用向量库 + 相似度召回？",options:["embedding 无法在本地运行且成本不可控","Agent 检索多是找特定符号而非猜相似需要精确匹配","向量库无法索引被指令文件和 Skill 覆盖的项目知识","SQLite 分页加载天然比 embedding 更省实时内存"],correct:1,explanation:"Agent 常要找函数定义、error 字符串、import 这类「特定东西」，相似度召回不如精确匹配。加上向量库实时性差（代码更新索引滞后）、chunk 丢上下文、embedding 有成本——四条对应 Grep 实时 / Read 读全文 / 本地零成本 / 精确匹配。"},{question:"OpenCode 不用独立记忆层（如 CC 的 memdir）。作者为什么认为这方面的覆盖已经够用？",options:["指令按需注入 + SQLite 持久化 + filterCompacted 已覆盖三块","文件系统足够表达记忆故数据库只存会话不必另建层","因为跨厂商环境不支持本地记忆文件所以放弃抽象层","记忆尚未覆盖但未来版本会补 memdir 因此暂不叠层"],correct:0,explanation:"记忆层想覆盖的三种能力——项目知识、会话历史、上下文自洽——分别已被指令文件按需注入、SQLite 持久化、filterCompacted 重排接管，再加 memdir 等于建平行重复子系统，复杂度上升收益有限。这是「功能完备性 vs 架构简洁」的取舍。"}];return(o,s)=>{const a=t("Quiz");return n(),e("div",null,[s[0]||(s[0]=h("",95)),l(a,{questions:i})])}}});export{c as __pageData,g as default};
